const d = $json.body ?? $json;
const title = String(d.title ?? '').trim();
const content = String(d.content ?? '').trim();
const source_url = String(d.source_url ?? '').trim();
if (!title || !content) throw new Error('title e content são obrigatórios.');
if (title.length > 180) throw new Error('title excede 180 caracteres.');
if (content.length > 60000) throw new Error('content excede 60000 caracteres.');
if (source_url && !/^https:\/\//i.test(source_url)) throw new Error('source_url deve usar HTTPS.');
const key = String(d.external_id ?? '').trim();
if (!key) throw new Error('external_id obrigatório para rastreabilidade e deduplicação.');
return [{json:{external_id:key,title,content,excerpt:String(d.excerpt??'').slice(0,500),source_url,editorial_status:'pending_review',publish_automatically:false,received_at:new Date().toISOString()}}];
